#!/usr/bin/env python3
import argparse
import json
from pathlib import Path
def validate(case):
    # JSON is user supplied (and often generated by another tool).  Validate
    # its shape before using values as dictionaries/sets; otherwise a malformed
    # case can abort the checker with an uncaught TypeError instead of producing
    # an actionable validation report.
    if not isinstance(case, dict):
        return {"claims":0,"evidence":0,"issues":["safety case must be a JSON object"],"ok":False}

    errors=[]

    def collect_nodes(value, kind):
        if not isinstance(value, list):
            errors.append(kind+" must be a list")
            return []
        nodes=[]
        for index, node in enumerate(value):
            if not isinstance(node, dict):
                errors.append("%s at index %d must be an object"%(kind[:-1], index))
                continue
            node_id=node.get("id")
            if not node_id:
                errors.append(kind[:-1]+" missing id")
                continue
            try:
                hash(node_id)
            except TypeError:
                errors.append(kind[:-1]+" id must be hashable")
                continue
            nodes.append((node_id, node))
        return nodes

    claim_nodes=collect_nodes(case.get("claims",[]), "claims")
    evidence_nodes=collect_nodes(case.get("evidence",[]), "evidence")
    claims={node_id:node for node_id,node in claim_nodes}
    evidence={node_id:node for node_id,node in evidence_nodes}
    # Node IDs are the names used by references in the argument graph.  A
    # duplicate ID makes a reference ambiguous (and the dictionary
    # comprehensions above silently discard one of the nodes), so reject it
    # instead of validating whichever duplicate happens to come last.
    # Do not call ``node_ids.count`` for every item here.  That turns a
    # perfectly valid large case into an O(n^2) scan and lets an accidentally
    # generated (or untrusted) case consume excessive CPU before validation
    # can report its result.  IDs have already been checked for hashability,
    # so a set gives us a linear pass while preserving first-seen order in the
    # diagnostic list.
    seen_ids=set()
    duplicate_ids=[]
    for node_id,_ in claim_nodes + evidence_nodes:
        if node_id in seen_ids:
            if node_id not in duplicate_ids:
                duplicate_ids.append(node_id)
        else:
            seen_ids.add(node_id)
    errors.extend("duplicate node id "+str(node_id) for node_id in duplicate_ids)
    # An empty graph cannot constitute a safety argument.  Previously an
    # empty JSON object (or one with no claims) returned ``ok=True`` because
    # there was nothing for the individual checks to reject.
    if not claims:
        errors.append("safety case has no claims")
    claim_supports={}
    for cid, claim in claim_nodes:
        supports=claim.get("supports",[])
        if not isinstance(supports, list):
            errors.append("%s supports must be a list"%cid)
            supports=[]
        else:
            valid_supports=[]
            for index, ref in enumerate(supports):
                try:
                    hash(ref)
                except TypeError:
                    errors.append("%s has unhashable support reference at index %d"%(cid,index))
                    continue
                valid_supports.append(ref)
            supports=valid_supports
        claim_supports[cid]=supports
        for ref in supports:
            if ref not in evidence and ref not in claims: errors.append("%s references missing %s"%(cid,ref))
        if not supports: errors.append("%s has no supporting evidence or subclaim"%cid)
    referenced=set(ref for supports in claim_supports.values() for ref in supports)
    for eid in evidence:
        if eid not in referenced: errors.append("orphan evidence %s"%eid)
    graph={cid:[ref for ref in claim_supports.get(cid,[]) if ref in claims] for cid in claims}
    # A safety case is one argument graph with a single top-level claim.  A
    # second claim that is never supported by another claim forms a separate
    # disconnected argument and would otherwise be silently accepted as if it
    # were part of the reviewed case.  Keep the first declared root for
    # backwards compatibility and report every additional root as orphaned.
    referenced_claims={ref for ref in referenced if ref in claims}
    root_claims=[cid for cid in claims if cid not in referenced_claims]
    for orphan in root_claims[1:]:
        errors.append("orphan claim "+str(orphan))
    visiting=set(); visited=set()
    def dfs(node):
        if node in visiting: errors.append("cycle detected at %s"%node); return
        if node in visited: return
        visiting.add(node)
        for child in graph.get(node,[]): dfs(child)
        visiting.remove(node); visited.add(node)
    for cid in graph: dfs(cid)
    return {"claims":len(claims),"evidence":len(evidence),"issues":errors,"ok":not errors}
def main(argv=None):
    p=argparse.ArgumentParser(description="Check a small safety argument graph"); p.add_argument("case",type=Path); a=p.parse_args(argv)
    try: report=validate(json.loads(a.case.read_text(encoding="utf-8")))
    # A case is read as UTF-8.  Invalid byte sequences raise
    # ``UnicodeDecodeError`` before ``json.loads`` gets a chance to report a
    # parse error; keep malformed files on the normal CLI error path instead
    # of leaking a traceback to CI users.
    except (OSError, UnicodeError, json.JSONDecodeError) as e: print("error: "+str(e)); return 2
    print(json.dumps(report,indent=2,ensure_ascii=False)); return 0 if report["ok"] else 1
if __name__=="__main__": raise SystemExit(main())
